```javascript
'use strict';

function createPolicyEvaluator(rules) {
  if (!Array.isArray(rules)) throw new TypeError('rules must be an array');
  const stored = rules.map(rule => {
    if (!rule || typeof rule !== 'object' || Array.isArray(rule) || typeof rule.principal !== 'string' || rule.principal.length === 0 || typeof rule.resource !== 'string' || rule.resource.length === 0 || !Array.isArray(rule.actions) || rule.actions.length === 0 || rule.actions.some(action => typeof action !== 'string' || action.length === 0)) throw new TypeError('invalid rule');
    return { principal: rule.principal, resource: rule.resource, actions: rule.actions.slice() };
  });
  return {
    canPerform(principal, resource, action) {
      if (typeof principal !== 'string' || principal.length === 0 || typeof resource !== 'string' || resource.length === 0 || typeof action !== 'string' || action.length === 0) throw new TypeError('invalid request');
      return stored.some(rule =>
        rule.principal === principal &&
        (rule.resource === '*' || rule.resource === resource) &&
        (rule.actions.includes('*') || rule.actions.includes(action))
      );
    }
  };
}

module.exports = { createPolicyEvaluator };
