'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['createPolicyEvaluator']);
const { createPolicyEvaluator } = api;

assert.throws(() => createPolicyEvaluator(), TypeError);
assert.throws(() => createPolicyEvaluator(null), TypeError);
for (const bad of [
  null,
  [],
  { principal: '', resource: 'doc', actions: ['read'] },
  { principal: 'alice', resource: '', actions: ['read'] },
  { principal: 'alice', resource: 'doc', actions: [] },
  { principal: 'alice', resource: 'doc', actions: [''] },
  { principal: 'alice', resource: 'doc', actions: 'read' }
]) assert.throws(() => createPolicyEvaluator([bad]), TypeError);

const empty = createPolicyEvaluator([]);
assert.strictEqual(empty.canPerform('alice', 'doc', 'read'), false);

const rules = [
  { principal: 'alice', resource: 'report', actions: ['read', 'share'] },
  { principal: '*', resource: 'public', actions: ['read'] },
  { principal: 'admin', resource: '*', actions: ['delete'] },
  { principal: 'root', resource: 'secret', actions: ['*'] }
];
const original = JSON.parse(JSON.stringify(rules));
const evaluator = createPolicyEvaluator(rules);
assert.deepStrictEqual(rules, original);
rules[0].principal = '*';
rules[0].actions.push('*');
assert.strictEqual(evaluator.canPerform('alice', 'report', 'read'), true);
assert.strictEqual(evaluator.canPerform('alice', 'report', 'share'), true);
assert.strictEqual(evaluator.canPerform('bob', 'report', 'read'), false);
assert.strictEqual(evaluator.canPerform('bob', 'public', 'read'), true);
assert.strictEqual(evaluator.canPerform('Bob', 'public', 'read'), true);
assert.strictEqual(evaluator.canPerform('bob', 'public', 'Read'), false);
assert.strictEqual(evaluator.canPerform('admin', 'anything', 'delete'), true);
assert.strictEqual(evaluator.canPerform('ADMIN', 'anything', 'delete'), false);
assert.strictEqual(evaluator.canPerform('root', 'secret', 'anything'), true);
assert.strictEqual(evaluator.canPerform('root', 'other', 'anything'), false);

for (const bad of [undefined, null, '', 1, {}, []]) {
  assert.throws(() => evaluator.canPerform(bad, 'r', 'a'), TypeError);
  assert.throws(() => evaluator.canPerform('p', bad, 'a'), TypeError);
  assert.throws(() => evaluator.canPerform('p', 'r', bad), TypeError);
}

